const $=s=>document.querySelector(s),money=n=>'$ '+Number(n||0).toLocaleString('es-CO'),icon={};
const IC={dash:'📊',usuarios:'🔐',clientes:'👥',productos:'📦',categorias:'🗂️',ofertas:'🏷️',pedidos:'🧾',ventas:'💰',inventario:'📦',proveedores:'🏭',pedidos_proveedor:'🚚',pagos:'💳',devoluciones:'↩️',servicio:'🎧',direcciones:'📍',reportes:'📈',costos:'🧮',identidad:'🎨'};
const BADGE=['estado','prioridad','rol','metodo'],GOOD=['Activo','Confirmado','Entregado','Aprobada','Reembolsada','Resuelto','Cerrado','Pagado','Recibido','Baja'],BAD=['Inactivo','Cancelado','Rechazada','Alta','Fallido'];
const bdg=v=>`<span class="b ${GOOD.includes(v)?'g':BAD.includes(v)?'r':'y'}">${v}</span>`;
let cart=[],F={q:'',e:'',s:'',cat:''},catalogFromDb=false;
const cartCount=()=>cart.reduce((sum,item)=>sum+item.cantidad,0);
const toast=(m,e)=>{$('#toast').innerHTML=`<div class="${e?'e':''}">${m}</div>`;setTimeout(()=>$('#toast').innerHTML='',2600)};
const modal=h=>$('#modal').innerHTML=`<div class="mb">${h}</div>`,close=()=>$('#modal').innerHTML='';window.closeModal=close;document.addEventListener('keydown',e=>{if(e.key==='Escape'&&$('#modal')?.innerHTML.trim())close()});document.addEventListener('click',e=>{if(e.target?.id==='modal')close()});
const confirmM=(msg,fn)=>{window._ok=()=>{close();fn()};modal(`<h3>Confirmar acción</h3><p>${msg}</p><div class="ma"><button class="btn o" onclick="closeModal()">Cancelar</button><button class="btn d" onclick="_ok()">Confirmar</button></div>`)};
const stockBadge=(a,min)=>a<=0?'<span class="b r">Sin stock</span>':a<=min?'<span class="b y">Stock bajo</span>':'<span class="b g">Stock normal</span>';
const low=()=>M.productos.r.filter(p=>p[4]<=3);
/* ---------- TIENDA ---------- */
const brandPlaceholder='<span class="brand-icon" data-brand-icon>▣</span>';
function applyTheme(){
    document.documentElement.classList.add('theme-dark');
    try { localStorage.removeItem('tm-theme'); } catch (_) {}
}
function toggleTheme(){applyTheme()}
async function applyBranding(){try{const r=await fetch('api_marca.php',{cache:'no-store'});if(!r.ok)return;const d=await r.json();const companyName=String(d.company_name||'TechMarket Online').trim()||'TechMarket Online';document.querySelectorAll('[data-company-name]').forEach(el=>{el.textContent=companyName;});document.title=companyName;if(d.logo_url){document.querySelectorAll('[data-brand-icon]').forEach(el=>{el.innerHTML='<img src="'+String(d.logo_url).replace(/"/g,'&quot;')+'" alt="Logo '+companyName.replace(/"/g,'&quot;')+'">';});let link=document.getElementById('tmFavicon')||document.querySelector('link[rel="icon"]');if(!link){link=document.createElement('link');link.rel='icon';document.head.appendChild(link)}const faviconUrl=new URL(d.logo_url,location.href);faviconUrl.searchParams.set('v',String(Date.now()));link.href=faviconUrl.href;}const hero=document.getElementById('heroBrandArt');if(hero&&d.catalog_logo_url)hero.innerHTML='<img class="catalog-brand-image" src="'+String(d.catalog_logo_url).replace(/"/g,'&quot;')+'" alt="Logo del catálogo">';applyTheme();}catch(_){}}
const nav=()=>`<div class="nav"><a class="logo" href="#/" onclick="scrollStoreTo('top',event)">${brandPlaceholder}<span data-company-name>TechMarket Online</span></a><div class="nav-search"><input id="tmSearch" placeholder="Buscar productos…" autocomplete="off" value="${escHtml(F.s||'')}" oninput="searchProducts(this.value)" onfocus="searchProducts(this.value)"><div id="tmSuggestions" class="search-suggestions" hidden></div></div><a href="#/" onclick="scrollStoreTo('top',event)">Inicio</a><a href="#/" onclick="scrollStoreTo('products',event)">Productos</a><a href="#/" onclick="scrollStoreTo('categories',event)">Categorías</a><a id="offersNav" href="#/" onclick="scrollStoreTo('offers',event)" hidden>Ofertas</a><a href="#/" onclick="scrollStoreTo('contact',event)">Contacto</a><a href="#/carrito">🛒 Carrito <b id="cc">${cartCount()}</b></a>${window.tmCustomer?`<a class="btn" href="#/cuenta">Mi cuenta</a>`:`<a class="btn" href="#/login">Iniciar sesión</a>`}</div>`;
function scrollStoreTo(where,event){if(event){event.preventDefault();}const go=()=>{const ids={top:'.hero',products:'#productsSection',categories:'#categoriesSection',offers:'#offersSection',about:'#aboutSection',contact:'#contactSection'};if(where==='offers'&&document.getElementById('offersSection')?.hidden)return;document.querySelector(ids[where]||'.hero')?.scrollIntoView({behavior:'smooth',block:'start'});};if(!location.hash.startsWith('#/')||location.hash!=='#/'){location.hash='#/';setTimeout(go,180)}else go()}
function searchProducts(value){F.s=String(value||'');if(location.hash==='#/'||location.hash===''||location.hash==='#'){drawGrid();}const box=document.getElementById('tmSuggestions');if(!box)return;const q=F.s.trim().toLocaleLowerCase('es');if(!q){box.hidden=true;box.innerHTML='';return;}const tokens=q.split(/\s+/).filter(Boolean);const candidates=M.productos.r.filter(p=>p[6]==='Activo').map(p=>({p,hay:(String(p[2]||'')+' '+String(p[1]||'')+' '+String(p[5]||'')).toLocaleLowerCase('es')})).map(x=>({...x,score:tokens.reduce((n,t)=>n+(x.hay.includes(t)?1:0),0)})).filter(x=>x.score>0).sort((a,b)=>b.score-a.score||a.p[2].localeCompare(b.p[2],'es')).slice(0,6);box.innerHTML=candidates.map(({p})=>`<button type="button" class="suggestion" onclick="chooseSearch(${Number(p[0])})"><span>${escHtml(p[2])}</span><small>${escHtml(p[1])}</small></button>`).join('')||'<div class="suggestion-empty">Sin coincidencias</div>';box.hidden=false;}
function chooseSearch(id){const p=M.productos.r.find(x=>Number(x[0])===Number(id));if(!p)return;F.s=p[2];if(location.hash!=='#/'){location.hash='#/';setTimeout(()=>{drawGrid();productDetail(id);},180)}else{drawGrid();productDetail(id)}const box=document.getElementById('tmSuggestions');if(box)box.hidden=true;const input=document.getElementById('tmSearch');if(input)input.value=p[2];}

const finalPrice=p=>Math.round(Number(p[3]||0)*(1-Math.max(0,Math.min(90,Number(p[8]||0)))/100));
const productImage=p=>{const fallback=(CATS.find(c=>c[0]===p[1])||[0,'📦'])[1];return p[7]?'<img src="'+escHtml(String(p[7]))+'" alt="'+escHtml(String(p[2]))+'" loading="lazy" onerror="this.onerror=null;this.replaceWith(Object.assign(document.createElement(\'span\'),{className:\'image-fallback\',textContent:'+JSON.stringify(fallback)+'}))">':'<span class="image-fallback">'+fallback+'</span>'};
const card=p=>{const discount=Math.max(0,Math.min(90,Number(p[8]||0))),price=finalPrice(p);return `<div class="pc"><button class="product-preview" onclick="productDetail(${Number(p[0])})" aria-label="Ver detalles de ${String(p[2]).replace(/"/g,'&quot;')}"><div class="im">${discount?`<span class="discount-badge">-${discount}%</span>`:''}${productImage(p)}</div></button><div class="bd"><small>${p[1]}</small><button class="product-name" onclick="productDetail(${Number(p[0])})">${p[2]}</button><small>${p[5]}</small><div class="row"><span>${discount?`<span class="old-price">${money(p[3])}</span> `:''}<span class="pr">${money(price)}</span></span>${p[4]<=0?'<span class="b r">Agotado</span>':p[4]<=3?`<span class="b y">Quedan ${p[4]}</span>`:`<small>${p[4]} en stock</small>`}</div><div class="product-actions"><button class="btn o" onclick="productDetail(${Number(p[0])})">Ver producto</button><button class="btn" ${p[4]<=0?'disabled':''} onclick="addToCart(${Number(p[0])})">🛒</button></div></div></div>`};
function productDetail(id){const p=M.productos.r.find(x=>Number(x[0])===Number(id));if(!p)return toast('No se encontró el producto.',1);const discount=Math.max(0,Math.min(90,Number(p[8]||0)));modal(`<div class="product-detail"><button class="detail-close" onclick="closeModal()" aria-label="Cerrar">✕</button><div class="detail-image">${productImage(p)}</div><div class="detail-info"><small>${escHtml(p[1])}</small><h2>${escHtml(p[2])}</h2>${discount?`<p><span class="discount-badge inline">-${discount}% OFF</span> <span class="old-price">${money(p[3])}</span></p>`:''}<h2 class="pr">${money(finalPrice(p))}</h2><p>${escHtml(p[5]||'Consulta con nuestro equipo para conocer más detalles de este producto.')}</p><p>${Number(p[4])>0?`Disponibles: ${Number(p[4])} unidades`:'Producto agotado'}</p><div class="ma"><button class="btn o" onclick="closeModal()">Cerrar</button><button class="btn" ${Number(p[4])<=0?'disabled':''} onclick="addToCart(${Number(p[0])});closeModal()">Agregar al carrito</button></div></div></div>`)}

function drawGrid(){if(!catalogFromDb){const grid=$('#grid');if(grid)grid.innerHTML='<p>Cargando catálogo real de MySQL…</p>';return}const q=(F.s||'').toLocaleLowerCase('es').trim().split(/\s+/).filter(Boolean),c=F.cat;const l=M.productos.r.filter(p=>p[6]==='Activo'&&q.every(t=>(String(p[2]||'')+' '+String(p[1]||'')+' '+String(p[5]||'')).toLocaleLowerCase('es').includes(t))&&(!c||(Array.isArray(window._tmCategoryFilterNames)?window._tmCategoryFilterNames.includes(p[1]):p[1]===c)));$('#grid').innerHTML=l.map(card).join('')||'<p>No hay productos que coincidan. Prueba con otra búsqueda.</p>'}
function addToCart(idProducto){
  const p=M.productos.r.find(x=>Number(x[0])===Number(idProducto));
  if(!p||p[6]!=='Activo')return toast('Este producto ya no está disponible.',1);
  if(Number(p[4])<=0)return toast('Este producto está agotado.',1);
  const item=cart.find(x=>x.id_producto===Number(idProducto));
  if(item){if(item.cantidad>=Number(p[4]))return toast('No puedes agregar más unidades de las disponibles.',1);item.cantidad++;}
  else cart.push({id_producto:Number(p[0]),nombre:p[2],precio:finalPrice(p),stock:Number(p[4]),cantidad:1});
  const badge=$('#cc');if(badge)badge.textContent=cartCount();toast('Producto agregado al carrito.');
}
function cartPage(){
  const total=cart.reduce((s,x)=>s+x.precio*x.cantidad,0);
  const contenido=cart.length?`<div class="tw"><table><thead><tr><th>Producto</th><th>Precio</th><th>Cantidad</th><th>Subtotal</th><th></th></tr></thead><tbody>${cart.map(x=>`<tr><td><b>${x.nombre}</b><br><small>Disponibles al cargar: ${x.stock}</small></td><td>${money(x.precio)}</td><td><button class="btn o s" onclick="changeCart(${x.id_producto},-1)">−</button> <b>${x.cantidad}</b> <button class="btn o s" onclick="changeCart(${x.id_producto},1)">+</button></td><td>${money(x.precio*x.cantidad)}</td><td><button class="btn d s" onclick="removeCart(${x.id_producto})">Quitar</button></td></tr>`).join('')}</tbody></table></div><div class="panel" style="margin-top:18px;display:flex;justify-content:space-between;align-items:center;gap:16px;flex-wrap:wrap"><h2>Total: ${money(total)}</h2><div><button class="btn o" onclick="cart=[];cartPage();toast('Carrito vaciado')">Vaciar carrito</button> <button class="btn" onclick="location.hash='#/checkout'">Continuar con la compra</button></div></div>`:`<div class="panel"><h3>Tu carrito está vacío</h3><p>Agrega productos del catálogo para comenzar una compra.</p><a class="btn" href="#/">Volver a la tienda</a></div>`;
  $('#app').innerHTML=nav()+`<div class="wrap" style="padding-top:28px;min-height:55vh"><div class="sec"><h2>Mi carrito</h2><a href="#/">Seguir comprando</a></div>${contenido}</div>`;
}
function changeCart(id,delta){const item=cart.find(x=>x.id_producto===Number(id));if(!item)return;if(delta>0&&item.cantidad>=item.stock)return toast('No hay más unidades disponibles según el último catálogo.',1);item.cantidad+=delta;if(item.cantidad<=0)cart=cart.filter(x=>x.id_producto!==Number(id));cartPage()}
function removeCart(id){cart=cart.filter(x=>x.id_producto!==Number(id));cartPage();toast('Producto retirado del carrito')}
async function checkout(){
  try { const auth=await fetch('api_cliente.php?action=me',{cache:'no-store'}); const authData=await auth.json(); window.tmCustomer=authData.authenticated?authData.user:null; if(!authData.authenticated){location.hash='#/login';toast('Inicia sesión o crea tu cuenta para finalizar la compra.');return;} } catch(e){location.hash='#/login';return;}
  if(!cart.length){location.hash='#/carrito';return;}
  const total=cart.reduce((s,x)=>s+x.precio*x.cantidad,0);
  $('#app').innerHTML=nav()+`<div class="auth" style="max-width:760px;width:calc(100% - 32px);margin:28px auto"><h2>Finalizar compra</h2><div class="fg"><label>Nombre completo<input id="coNombre" maxlength="255" required></label><label>Correo electrónico<input id="coCorreo" type="email" maxlength="255" required></label><label>Teléfono<input id="coTelefono" maxlength="255" required></label><label>Tipo de documento<select id="coTipo"><option>CC</option><option>CE</option><option>NIT</option><option>Pasaporte</option></select></label><label>Número de documento<input id="coDocumento" maxlength="100" required></label><label class="f">Dirección de entrega<input id="coDireccion" maxlength="255" required></label><label>Ciudad<input id="coCiudad" maxlength="255" required></label><label>Departamento<input id="coDepartamento" maxlength="255" required></label><label>Código postal (opcional)<input id="coPostal" maxlength="255"></label><label class="f">Referencia de entrega (opcional)<input id="coReferencia" maxlength="255" placeholder="Apartamento, barrio, indicaciones…"></label><label>Tipo de pago<select id="coModoPago" onchange="updatePaymentOptions()"><option value="real">Pago real</option><option value="prueba">Pago de prueba</option></select></label><label class="f">Método de pago<select id="coPago"><option value="Contraentrega">Contraentrega</option><option value="Transferencia bancaria">Transferencia bancaria</option></select></label></div><div class="panel" style="margin-top:18px"><h3>Resumen: ${cartCount()} unidades · ${money(total)}</h3></div><div class="ma"><a class="btn o" href="#/carrito">Volver al carrito</a><button class="btn" id="checkoutBtn" onclick="placeOrder()">Confirmar pedido</button></div><p id="checkoutError" style="color:#b91c1c"></p></div>`;
  const cu=window.tmCustomer||{};const set=(id,val)=>{const el=$('#'+id);if(el)el.value=val||''};set('coNombre',[cu.nombre,cu.apellidos].filter(Boolean).join(' '));set('coCorreo',cu.correo);set('coTelefono',cu.telefono);set('coTipo',cu.tipo_documento);set('coDocumento',cu.numero_documento);
  try{const ar=await fetch('api_cliente.php?action=addresses',{cache:'no-store'});const ad=await ar.json();const addresses=(ad.rows||[]).filter(a=>Number(a.estado)===1);if(addresses.length){const first=addresses[0];set('coDireccion',first.direccion_linea);set('coCiudad',first.ciudad);set('coDepartamento',first.departamento);set('coPostal',first.codigo_postal);set('coReferencia',first.referencia);}}catch(_){}
}
function updatePaymentOptions(){const mode=document.getElementById('coModoPago')?.value||'real',sel=document.getElementById('coPago');if(!sel)return;const options=mode==='prueba'?[['Tarjeta de prueba','Tarjeta de prueba'],['Transferencia de prueba','Transferencia de prueba']]:[['Contraentrega','Contraentrega'],['Transferencia bancaria','Transferencia bancaria']];sel.innerHTML=options.map(([v,t])=>`<option value="${v}">${t}</option>`).join('');}
async function placeOrder(){
  const btn=$('#checkoutBtn');if(btn){btn.disabled=true;btn.textContent='Procesando…';}
  const body={action:'crear',nombre:$('#coNombre').value.trim(),correo:$('#coCorreo').value.trim(),telefono:$('#coTelefono').value.trim(),tipo_documento:$('#coTipo').value,numero_documento:$('#coDocumento').value.trim(),direccion:$('#coDireccion').value.trim(),ciudad:$('#coCiudad').value.trim(),departamento:$('#coDepartamento').value.trim(),codigo_postal:$('#coPostal').value.trim(),referencia:$('#coReferencia').value.trim(),metodo_pago:$('#coPago').value,items:cart.map(x=>({id_producto:x.id_producto,cantidad:x.cantidad}))};
  try{
    const response=await fetch('api_pedidos_ventas.php',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)});
    const data=await response.json();if(!response.ok)throw new Error(data.error||'No se pudo registrar el pedido.');
    cart=[];showCustomerPaymentStep(data,body.metodo_pago);
  }catch(e){const err=$('#checkoutError');if(err)err.textContent=e.message||'Ocurrió un error al procesar la compra.';if(btn){btn.disabled=false;btn.textContent='Confirmar pedido';}}
}


function showCustomerPaymentStep(data,method){
  const isCard=String(method).startsWith('Tarjeta');
  const isTransfer=String(method).startsWith('Transferencia');
  const isTest=String(method).includes('prueba');
  const id=Number(data.id_pedido),total=Number(data.total);window._paymentTotal=total;window._paymentReceipt=data.comprobante||'';
  const base=`<div class="panel" style="text-align:left;margin:18px 0"><p><b>Pedido:</b> #${id} &nbsp; <b>Comprobante:</b> ${data.comprobante}</p><h2 style="margin:8px 0">Total a pagar: ${money(total)}</h2></div>`;
  let content='';
  if(isCard){
    content=`<div style="border-radius:16px;background:linear-gradient(135deg,#172554,#4f46e5);color:white;padding:22px;margin:18px 0;text-align:left"><small>PAGO DE PRUEBA</small><div style="font-size:26px;letter-spacing:3px;margin:25px 0 18px">•••• •••• •••• ••••</div><div style="display:flex;justify-content:space-between;gap:12px"><span>Tarjeta de prueba</span><span>VISA / MASTERCARD</span></div></div><div class="fg" style="text-align:left"><label class="f">Nombre del titular<input id="payHolder" autocomplete="off" placeholder="NOMBRE COMO APARECE EN LA TARJETA" maxlength="80"></label><label class="f">Número de tarjeta de prueba<input id="payNumber" inputmode="numeric" autocomplete="off" placeholder="4242 4242 4242 4242" maxlength="23" oninput="this.value=this.value.replace(/[^0-9 ]/g,'').slice(0,23)"></label><label>Vencimiento<input id="payExpiry" inputmode="numeric" placeholder="MM/AA" maxlength="5" oninput="formatExpiry(this)"></label><label>CVV de prueba<input id="payCvv" inputmode="numeric" placeholder="123" maxlength="4" oninput="this.value=this.value.replace(/\\D/g,'').slice(0,4)"></label></div><div class="note">Usa únicamente datos ficticios de prueba. No ingreses información de una tarjeta real.</div><button class="btn" id="payActionBtn" style="width:100%;margin-top:12px" onclick="simulateCardPayment(${id})">🔒 Pagar ${money(total)}</button><p id="payError" style="color:#b91c1c"></p>`;
  }else if(isTransfer && isTest){
    content=`<div class="panel" style="text-align:left"><h3>Transferencia de prueba</h3><p>Referencia: <b>TM-${id}</b></p><p>Valor: <b>${money(total)}</b></p></div><button class="btn" id="payActionBtn" style="width:100%;margin-top:12px" onclick="registerDemoTransfer(${id})">Confirmar transferencia de prueba</button><p id="payError" style="color:#b91c1c"></p><p id="transferInfo"></p>`;
  }else if(isTransfer){
    content=`<div class="panel" style="text-align:left"><h3>Transferencia bancaria</h3><p>Pedido: <b>#${id}</b></p><p>Valor: <b>${money(total)}</b></p><p>El pedido quedó pendiente de pago. La tienda debe facilitar los datos bancarios para completar la transferencia.</p></div>`;
  }else{
    content=`<div style="font-size:54px;margin:16px">📦</div><h3>Elegiste pagar al recibir tu pedido</h3><p>No tienes que pagar ahora. Cuando recibas el producto, el administrador registrará el cobro en el sistema.</p><div class="note">Estado del pago: <b>Pendiente de cobro</b>. El administrador debe marcar el pedido como Entregado y luego confirmar el pago.</div>`;
  }
  $('#app').innerHTML=nav()+`<div class="auth" style="max-width:700px;width:calc(100% - 32px);margin:32px auto"><div style="text-align:center"><div style="font-size:48px">${isCard?'💳':isTransfer?'🏦':'📦'}</div><h2>${isCard?'Pago con tarjeta':isTransfer?'Transferencia bancaria':'Pago contraentrega'}</h2><p>Tu pedido fue registrado correctamente. Completa el siguiente paso para este método de pago.</p></div>${base}${content}<div class="ma"><a class="btn o" href="#/">Volver a la tienda</a></div></div>`;
}
function formatExpiry(input){let v=input.value.replace(/\D/g,'').slice(0,4);if(v.length>2)v=v.slice(0,2)+'/'+v.slice(2);input.value=v;}
async function simulateCardPayment(id){
  const holder=$('#payHolder')?.value.trim()||'',number=($('#payNumber')?.value||'').replace(/\D/g,''),expiry=$('#payExpiry')?.value||'',cvv=$('#payCvv')?.value||'';
  const err=$('#payError'),btn=$('#payActionBtn');
  if(!holder||number.length!==16||!/^\d{2}\/\d{2}$/.test(expiry)||Number(expiry.slice(0,2))<1||Number(expiry.slice(0,2))>12||cvv.length<3){if(err)err.textContent='Revisa los datos ficticios: titular, 16 dígitos, vencimiento MM/AA y CVV de 3 o 4 dígitos.';return;}
  if(btn){btn.disabled=true;btn.textContent='⏳ Autorizando pago de prueba…';}if(err)err.textContent='';
  try{await new Promise(resolve=>setTimeout(resolve,900));const response=await fetch('api_pedidos_ventas.php',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({action:'confirmar_pago',id_pedido:Number(id)})});const data=await response.json();if(!response.ok)throw new Error(data.error||'La autorización de prueba no fue aprobada.');
    $('#app').innerHTML=nav()+`<div class="auth" style="max-width:650px;width:calc(100% - 32px);margin:45px auto;text-align:center"><div style="font-size:64px">✅</div><h2>¡Pago aprobado!</h2><p>El pago de prueba fue aprobado.</p><div class="panel"><p>Pedido: <b>#${id}</b></p><p>Comprobante: <b>${window._paymentReceipt||'Consulta el comprobante en administración'}</b></p><h2>${money(window._paymentTotal||0)}</h2><p>Estado del pago: ${bdg('Pagado')}</p></div><div class="ma"><a class="btn o" href="#/">Volver a la tienda</a></div></div>`;
  }catch(e){if(err)err.textContent=e.message;if(btn){btn.disabled=false;btn.textContent='🔒 Intentar pago de prueba';}}
}
