let tmGoogleScriptPromise=null;
async function setupGoogleButton(containerId){
 const container=document.getElementById(containerId);if(!container)return;
 try{
  const cfg=await fetch('api_cliente.php?action=google_config',{cache:'no-store'}).then(r=>r.json());
  if(!cfg.client_id || !/^[0-9]+-[A-Za-z0-9_-]+\.apps\.googleusercontent\.com$/.test(cfg.client_id)){container.style.display='none';const divider=document.getElementById('googleDivider');if(divider)divider.style.display='none';return;}
  const divider=document.getElementById('googleDivider');if(divider)divider.style.display='block';
  if(!tmGoogleScriptPromise){tmGoogleScriptPromise=new Promise((resolve,reject)=>{if(window.google?.accounts?.id){resolve();return;}const script=document.createElement('script');script.src='https://accounts.google.com/gsi/client';script.async=true;script.defer=true;script.onload=resolve;script.onerror=()=>reject(new Error('No se pudo cargar el acceso de Google.'));document.head.appendChild(script);});}
  await tmGoogleScriptPromise;
  google.accounts.id.initialize({client_id:cfg.client_id,callback:handleGoogleCredential,auto_select:false});
  google.accounts.id.renderButton(container,{type:'standard',theme:'outline',size:'large',text:'continue_with',shape:'rectangular',width:300,locale:'es'});
 }catch(e){container.style.display='none';const divider=document.getElementById('googleDivider');if(divider)divider.style.display='none';console.error('No se pudo cargar el acceso con Google.',e);}
}
async function handleGoogleCredential(response){
 const err=document.getElementById('googleError');if(err)err.textContent='';
 try{const r=await fetch('api_cliente.php',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({action:'google_login',credential:response.credential})});const d=await r.json();if(!r.ok)throw new Error(d.error||'No se pudo iniciar con Google.');
  if(d.needs_profile){window.tmGoogleProfile=d;location.hash='#/registro-google';return;}
  const me=await fetch('api_cliente.php?action=me',{cache:'no-store'}).then(x=>x.json());window.tmCustomer=me.authenticated?me.user:null;toast(d.message||'Sesión iniciada con Google.');location.hash='#/cuenta';
 }catch(e){if(err)err.textContent=e.message;else toast(e.message,1);}
}
