async function uploadBrandLogo(event,tipo='principal'){event.preventDefault();if(window.tmUser?.rol!=='Jefe')return toast('No tienes permiso para cambiar el logo.',1);const catalogo=tipo==='catalogo',file=$(catalogo?'#catalogBrandFile':'#brandFile')?.files?.[0];if(!file)return toast('Selecciona una imagen.',1);const status=$(catalogo?'#catalogBrandUploadStatus':'#brandUploadStatus');if(status)status.textContent=' Guardando…';try{const form=new FormData();form.append('logo',file);form.append('tipo',tipo);const r=await fetch('api_marca.php',{method:'POST',body:form});const raw=await r.text();let d;try{d=JSON.parse(raw)}catch(_){throw new Error('El servidor no devolvió JSON válido. Revisa los registros de Render.')}if(!r.ok)throw new Error(d.error||'No se pudo subir el logo.');await applyBranding();await loadBrandPreview();if(status)status.textContent=' Guardado correctamente.';toast('Logo actualizado.');}catch(e){if(status)status.textContent=' '+e.message;toast(e.message||'No se pudo actualizar el logo.',1)}}

