function openForm(k,id){if(k==='categorias'){openCategoryForm(id||0);return;}_openFormOriginal(k,id);if(k==='productos'){window._discountProductId=Number(id||0);loadDiscountCost(Number(id||0));}if(k==='usuarios'){if(!id&&$('#f3'))$('#f3').value='Empleado';$('#modal .mb')?.insertAdjacentHTML('beforeend',`<label class="f">${id?'Cambiar contraseña (opcional)':'Contraseña inicial'}<input id="fpass" type="password" minlength="12" autocomplete="new-password" placeholder="Mínimo 12 caracteres" ${id?'':'required'}></label>`)}}
async function save(k,id){
  const m=M[k];if(!m)return toast('Módulo no encontrado.',1);
  if(k==='categorias'){
    const parent=document.getElementById('f0')?.value||'';
    if(window._tmCategoryKind==='subcategoria'&&!parent)return toast('Selecciona la categoría principal donde irá esta subcategoría.',1);
    if(window._tmCategoryKind==='principal'&&parent)return toast('Una categoría principal no debe depender de otra categoría.',1);
  }
  if(!DB_MODULES.includes(k))return saveOriginalTechMarket(k,id);
  const v=m.c.slice(1).map((c,i)=>{const el=$('#f'+i);if(!el)return '';const x=el.value;return el.type==='number'?Number(x):x});
  const req=m.c.slice(1).findIndex((c,i)=>v[i]===''&&!/fecha_cierre|referencia|categoria_principal|descripcion|id_usuario/.test(c[0]));
  if(req>=0)return toast('Completa el campo "'+m.c[req+1][1]+'"',1);
  if(k==='usuarios'&&v[3]==='Empleado')v[3]='Staff';const payload={action:'guardar_modulo',modulo:k,id:Number(id||0),values:v};if(k==='usuarios')payload.password=$('#fpass')?.value||'';
  try{const r=await fetch('api_administracion.php',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)});const d=await r.json();if(!r.ok)throw new Error(d.error||'No se pudo guardar.');close();toast(d.message||'Guardado en MySQL.');await loadDbModule(k);if(k==='categorias')await refreshCategoryOptions()}catch(e){toast(e.message||'Error al guardar.',1)}
}
function tog(k,id){
 if(!DB_MODULES.includes(k))return togOriginalTechMarket(k,id);
 const m=M[k],r=m.r.find(x=>Number(x[0])===Number(id));if(!r)return toast('Registro no encontrado.',1);const idx=m.c.findIndex(c=>c[0]==='estado');const next=r[idx]==='Activo'?'Inactivo':'Activo';confirmM(`¿Cambiar el estado del registro seleccionado a ${next}?`,async()=>{try{const res=await fetch('api_administracion.php',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({action:'estado',modulo:k,id:Number(id),estado:next})});const d=await res.json();if(!res.ok)throw new Error(d.error||'No se pudo cambiar el estado.');toast(d.message||'Estado actualizado.');await loadDbModule(k)}catch(e){toast(e.message,1)}})
}
