async function deleteAdminRecord(modulo,id){
 const names={usuarios:'usuario',clientes:'cliente',categorias:'categoría',proveedores:'proveedor',direcciones:'dirección',servicio:'ticket de servicio',productos:'producto',pedidos:'pedido',ventas:'venta',pagos:'pago',inventario:'registro de inventario',pedidos_proveedor:'pedido a proveedor',devoluciones:'devolución',garantias:'garantía'};
 if(!confirm(`¿Eliminar definitivamente este registro de ${names[modulo]||modulo}? Esta acción no se puede deshacer. También se eliminarán los registros dependientes que estén vinculados.`))return;
 try{const product=modulo==='productos';const r=await fetch(product?'api_gestion_productos.php':'api_administracion.php',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(product?{action:'eliminar',id:Number(id)}:{action:'eliminar_modulo',modulo,id:Number(id)})});const d=await r.json();if(!r.ok)throw new Error(d.error||'No se pudo eliminar el registro.');toast(d.message||'Registro eliminado.');if(product){await loadAdminProducts();mod('productos')}else if(['pedidos','ventas','pagos','devoluciones','garantias','inventario','pedidos_proveedor'].includes(modulo)){if(modulo==='pedidos'||modulo==='ventas')await loadOrdersAndRender(modulo);else if(modulo==='pagos')await loadPaymentsAndRender();else if(modulo==='devoluciones'||modulo==='garantias')await loadReturnsAndWarranties();else if(modulo==='inventario')await loadInventoryAndRender();else if(modulo==='pedidos_proveedor')await loadSupplierOrders();else await loadDbModule(modulo)}else{await loadDbModule(modulo);if(modulo==='categorias')await refreshCategoryOptions();}}
 catch(e){toast(e.message||'No se pudo eliminar el registro.',1)}
}
