async function loadSupplierOrders(){try{const r=await fetch('api_administracion.php?vista=pedidos_proveedor',{cache:'no-store'});const d=await r.json();if(!r.ok)throw new Error(d.error||'No se pudieron cargar las compras.');const rows=d.rows||[];window._supplierOrderRows=rows;const html=`<div class="tools"><input id="supplierOrderSearch" placeholder="Buscar orden o proveedor" oninput="filterSupplierOrders()"><button class="btn" onclick="newSupplierOrder()">Nueva compra a proveedor</button><button class="btn o" onclick="loadSupplierOrders()">Actualizar</button></div><div class="tw"><table><thead><tr><th>Proveedor</th><th>Responsable</th><th>Fecha</th><th>Estado</th><th>Costo total</th><th>Acciones</th></tr></thead><tbody id="supplierOrderRows">${supplierOrderRowsHtml(rows)}</tbody></table></div>`;shell('pedidos_proveedor','Pedidos a proveedores',html)}catch(e){shell('pedidos_proveedor','Pedidos a proveedores',`<div class="note" style="color:#b91c1c">${String(e.message||e).replace(/[<>]/g,'')}</div><button class="btn o" onclick="loadSupplierOrders()">Reintentar</button>`)} }
function supplierOrderRowsHtml(rows){return rows.map(r=>`<tr><td>${r[1]}</td><td>${r[2]}</td><td>${r[3]}</td><td>${bdg(r[4])}</td><td>${money(r[5])}</td><td><button class="btn o s" onclick="supplierOrderDetail(${Number(r[0])})">Detalle</button>${r[4]==='Pendiente'?` <button class="btn g s" onclick="receiveSupplierOrder(${Number(r[0])})">Recibir</button><button class="btn d s" onclick="cancelSupplierOrder(${Number(r[0])})">Cancelar</button>`:''}${window.tmUser?.rol==='Jefe'?` <button class="btn d s" onclick="deleteSupplierOrder(${Number(r[0])})">Eliminar</button>`:''}</td></tr>`).join('')||'<tr><td colspan="6">No hay compras a proveedores registradas.</td></tr>'}
function filterSupplierOrders(){const q=($('#supplierOrderSearch')?.value||'').toLowerCase();const rows=(window._supplierOrderRows||[]).filter(r=>r.join(' ').toLowerCase().includes(q));const b=$('#supplierOrderRows');if(b)b.innerHTML=supplierOrderRowsHtml(rows)}
async function newSupplierOrder(){try{const [a,b,c]=await Promise.all(['proveedores','staff','productos'].map(v=>fetch('api_administracion.php?vista='+v,{cache:'no-store'}).then(r=>r.json())));const providers=a.rows||[],staff=b.rows||[],products=c.rows||[];if(!providers.length||!staff.length||!products.length)throw new Error('Necesitas al menos un proveedor, un empleado activo y un producto.');modal(`<h3>Nuevo pedido a proveedor</h3><div class="fg"><label class="f">Proveedor<select id="spoProvider">${providers.filter(x=>x[7]==='Activo').map(x=>`<option value="${x[0]}">${x[2]} · ${x[1]}</option>`).join('')}</select></label><label>Empleado responsable<select id="spoStaff">${staff.filter(x=>x[5]==='Activo').map(x=>`<option value="${x[0]}">${x[2]}</option>`).join('')}</select></label><label>Producto<select id="spoProduct">${products.filter(x=>Number(x.estado)===1||x.estado==='Activo').map(x=>`<option value="${x.id_producto}">${x.nombre} (stock ${x.stock})</option>`).join('')}</select></label><label>Cantidad<input id="spoQty" type="number" min="1" step="1" value="1"></label><label>Costo unitario (COP)<input id="spoCost" type="number" min="1" step="0.01" placeholder="Costo de compra"></label><label>Fecha de orden<input id="spoDate" type="date" value="${new Date().toISOString().slice(0,10)}"></label></div><p class="note">Se crea una orden con una línea de producto. Puedes crear órdenes adicionales para otros productos. Al recibirla se suman las unidades al stock y queda un movimiento de inventario.</p><div id="spoError" style="color:#b91c1c"></div><div class="ma"><button class="btn o" onclick="closeModal()">Cancelar</button><button class="btn" onclick="saveSupplierOrder()">Crear orden</button></div>`)}catch(e){toast(e.message||'No se pudo abrir el formulario.',1)}}
async function saveSupplierOrder(){const payload={action:'crear_pedido_proveedor',id_proveedor:Number($('#spoProvider')?.value),id_usuario_staff:Number($('#spoStaff')?.value),id_producto:Number($('#spoProduct')?.value),cantidad:Number($('#spoQty')?.value),costo_unitario:Number($('#spoCost')?.value),fecha_orden:$('#spoDate')?.value};try{const r=await fetch('api_administracion.php',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)});const d=await r.json();if(!r.ok)throw new Error(d.error||'No se pudo crear la orden.');close();toast(d.message||'Orden creada.');await loadSupplierOrders()}catch(e){const t=$('#spoError');if(t)t.textContent=e.message;else toast(e.message,1)}}
async function supplierOrderDetail(id){try{const r=await fetch('api_administracion.php?vista=detalle_pedido_proveedor&id='+id,{cache:'no-store'});const d=await r.json();if(!r.ok)throw new Error(d.error||'No se pudo consultar el detalle.');modal(`<h3>Detalle de compra</h3><div class="tw"><table><thead><tr><th>Producto</th><th>Cantidad</th><th>Costo unitario</th><th>Total</th></tr></thead><tbody>${(d.rows||[]).map(x=>`<tr><td>${x.producto}</td><td>${x.cantidad}</td><td>${money(x.costo_unitario)}</td><td>${money(x.total)}</td></tr>`).join('')||'<tr><td colspan="4">Sin productos.</td></tr>'}</tbody></table></div><div class="ma"><button class="btn o" onclick="closeModal()">Cerrar</button></div>`)}catch(e){toast(e.message,1)}}
function receiveSupplierOrder(id){confirmM(`¿Confirmas que recibiste físicamente los productos de esta orden? El stock aumentará y la recepción quedará registrada.`,async()=>{try{const r=await fetch('api_administracion.php',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({action:'recibir_pedido_proveedor',id_pedido_proveedor:id})});const d=await r.json();if(!r.ok)throw new Error(d.error||'No se pudo recibir el pedido.');toast(d.message||'Compra recibida.');await loadSupplierOrders()}catch(e){toast(e.message,1)}})}
function deleteSupplierOrder(id){deleteAdminRecord('pedidos_proveedor',Number(id))}
function cancelSupplierOrder(id){confirmM(`¿Cancelar esta orden al proveedor? No se modificará el inventario.`,async()=>{try{const r=await fetch('api_administracion.php',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({action:'cancelar_pedido_proveedor',id_pedido_proveedor:id})});const d=await r.json();if(!r.ok)throw new Error(d.error||'No se pudo cancelar.');toast(d.message||'Pedido cancelado.');await loadSupplierOrders()}catch(e){toast(e.message,1)}})}

const _routeBeforeIntegral=routeOriginalTechMarket;
let tmRouteCheck=0;
async function route(){applyBranding();const h=location.hash.replace('#/','').split('/');const k=h[1]||'dashboard';if(h[0]==='registro-google'){googleRegisterPage();return;}if(h[0]==='admin'&&k==='staff'){location.hash='#/admin/usuarios';return;}if(h[0]==='admin'){const check=++tmRouteCheck;try{const r=await fetch('api_auth.php?action=me',{cache:'no-store'});const d=await r.json();if(check!==tmRouteCheck)return;if(!r.ok||!d.authenticated){const back=encodeURIComponent(location.hash||'#/admin/dashboard');location.href='acceso-empresa.php?return='+back;return;}window.tmUser=d.user;if(!tmUiCan(d.user.rol,k)){shell(k,'Acceso restringido','<div class="note">Tu rol no tiene permiso para abrir este módulo. Si necesitas acceso, solicita autorización al Jefe.</div>');return;}}catch(e){location.href='acceso-empresa.php?return='+encodeURIComponent(location.hash||'#/admin/dashboard');return;}}if(h[0]==='acceso-empresa'){location.href='acceso-empresa.php';return;}if(h[0]==='cuenta'){customerAccount();return;}if(h[0]==='admin'&&DB_MODULES.includes(k)){F={q:'',e:'',s:'',cat:''};close();shell(k,M[k].t,'<p>Cargando registros desde MySQL…</p>');loadDbModule(k);scrollTo(0,0);return}if(h[0]==='admin'&&k==='pedidos_proveedor'){F={q:'',e:'',s:'',cat:''};close();shell(k,'Pedidos a proveedores','<p>Cargando compras desde MySQL…</p>');loadSupplierOrders();scrollTo(0,0);return}_routeBeforeIntegral();}

// Inicializar siempre la aplicación, incluso si falla una consulta secundaria.
applyTheme();
addEventListener('hashchange',route);
(async function bootTechMarket(){
  let customer={authenticated:false}, categories=[];
  try { customer=await fetch('api_cliente.php?action=me',{cache:'no-store'}).then(r=>r.ok?r.json():{authenticated:false}); } catch(_) {}
  window.tmCustomer=customer.authenticated?customer.user:null;
  try { const r=await fetch('api_categorias.php',{cache:'no-store'}); if(r.ok){const data=await r.json();categories=Array.isArray(data)?data:[];} } catch(_) {}
  try { applyCategories(categories); } catch(error) { console.error('No se pudieron aplicar las categorías.',error); }
  try { await route(); } catch(error) { console.error('Error al iniciar TechMarket.',error); const root=$('#app'); if(root)root.innerHTML='<div class="auth"><h2>No se pudo cargar TechMarket</h2><p>Actualiza la página o vuelve a intentarlo.</p><button class="btn" onclick="location.reload()">Reintentar</button></div>'; }
})();
